export function DragAndDropUpload({
  label = "{{label}}",
  hint = "{{hint}}",
  accept = "{{accept}}",
  multiple = {{multiple}},
  accent = "{{accent}}",
}) {
  return (
    <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430", maxWidth: 280 }}>
      <span style={{ display: "block", marginBottom: 6, fontWeight: 500 }}>{label}</span>
      <label style={{
        display: "flex", flexDirection: "column", alignItems: "center", gap: 4, textAlign: "center",
        padding: "22px 14px", border: "1.5px dashed #24143050", borderRadius: 10, background: "#FAF7F2", cursor: "pointer",
      }}>
        <input type="file" accept={accept} multiple={multiple} style={{ position: "absolute", width: 1, height: 1, overflow: "hidden", opacity: 0 }} />
        <span aria-hidden="true" style={{ fontSize: 18, color: accent }}>&#8593;</span>
        <span style={{ fontSize: 13 }}>{hint}</span>
        <span style={{ fontSize: 11, color: "#24143080" }}>{accept}</span>
      </label>
    </div>
  );
}
